# Helper function for popcount (bit counting)
# Using bin().count('1') for compatibility.
# If Python >= 3.10, int.bit_count() is potentially faster.
def _popcount(n: int) -> int:
    """Counts the number of set bits (1s) in the binary representation of n."""
    if n < 0:
        # This case is unlikely given the problem context but handled defensively.
        # Standard bin() behavior for negative numbers might not be desired Hamming distance.
        # Assuming inputs to Hamming distance derived from XOR are non-negative.
        raise ValueError("Popcount input must be non-negative")
    return bin(n).count('1')

class ExclusivityParticlesCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom
        # Threshold for switching between exhaustive and random search
        # Adjust based on performance testing if needed.
        self.DIMENSION_THRESHOLD = 21 # Use exhaustive for d <= 20
        # Time limit for random search in seconds (e.g., 4.5 minutes)
        self.RANDOM_SEARCH_TIME_LIMIT = 270.0

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def _list_to_int(self, p: List[int]) -> int:
        """Converts a binary list to its integer representation."""
        val = 0
        for bit in p:
            if bit not in (0, 1):
                 raise ValueError("Invalid bit value in particle list")
            val = (val << 1) | bit
        return val

    def _int_to_binary_list(self, n: int, d: int) -> List[int]:
        """Converts an integer to its d-bit binary list representation."""
        if d == 0:
            # Handle 0-dimension case
            return [] if n == 0 else self._raise_value_error("Integer out of range for 0 bits")
        if n < 0 or n >= (1 << d):
             # Error if integer is outside the expected range [0, 2^d - 1]
             self._raise_value_error(f"Integer {n} out of range for d={d} bits")

        # Use format string to ensure correct length with leading zeros
        binary_string = format(n, f'0{d}b')
        return [int(bit) for bit in binary_string]

    def _raise_value_error(self, message: str):
        """Helper to raise ValueError, allowing use in expressions if needed."""
        raise ValueError(message)

    def _hamming_distance_int(self, n1: int, n2: int) -> int:
        """Calculates Hamming distance between two non-negative integers using bitwise ops."""
        if n1 < 0 or n2 < 0:
             raise ValueError("Hamming distance requires non-negative integers")
        xor_val = n1 ^ n2
        return _popcount(xor_val)

    def _find_particle_exhaustive(self, dimension: int, distance: int, existing_particles_int: set) -> Optional[List[int]]:
        """Performs exhaustive search for a valid particle."""
        num_possible_particles = 1 << dimension
        for i in range(num_possible_particles):
            candidate_int = i
            is_valid = True
            # No need to check if existing_particles_int is empty; the loop handles it.
            for p_int in existing_particles_int:
                try:
                    dist = self._hamming_distance_int(candidate_int, p_int)
                    if dist < distance:
                        is_valid = False
                        break # Stop checking this candidate
                except ValueError as e:
                     # Error during Hamming distance (e.g., unexpected negative intermediate)
                     print(f"Error calculating Hamming distance: {e}")
                     is_valid = False # Treat as invalid
                     break

            if is_valid:
                 # Found a valid particle. Convert to list and return.
                 # Assume distance >= 1, so valid candidate is guaranteed not in existing_particles_int.
                 try:
                     return self._int_to_binary_list(candidate_int, dimension)
                 except ValueError as e:
                      # Error during conversion (should not happen for valid i)
                      print(f"Error converting valid integer {candidate_int} to binary list: {e}")
                      # Continue searching as this indicates an unexpected issue.
                      pass

        return None # No valid particle found

    def _find_particle_random(self, dimension: int, distance: int, existing_particles_int: set, time_limit_seconds: float) -> Optional[List[int]]:
        """Performs randomized search for a valid particle within a time limit."""
        num_possible_particles = 1 << dimension
        if num_possible_particles == 0:
            # Handle d=0: only point is [], check if it's already placed.
            return None if 0 in existing_particles_int else []

        start_time = time.time()

        # Use a set to track tried candidates for moderately large d to avoid re-checking
        # Avoid for very large d (e.g., d > 28) to limit memory usage.
        use_tried_set = dimension <= 28
        tried_candidates = set() if use_tried_set else None
        max_attempts_reached = False

        while time.time() - start_time < time_limit_seconds:
            if use_tried_set and len(tried_candidates) == num_possible_particles:
                 # If we have tried all possible unique candidates
                 max_attempts_reached = True
                 break # Search space exhausted

            candidate_int = random.randint(0, num_possible_particles - 1)

            if use_tried_set:
                if candidate_int in tried_candidates:
                    continue # Skip if already tried
                tried_candidates.add(candidate_int)

            # Check validity
            is_valid = True
            for p_int in existing_particles_int:
                try:
                    dist = self._hamming_distance_int(candidate_int, p_int)
                    if dist < distance:
                        is_valid = False
                        break
                except ValueError as e:
                     print(f"Error calculating Hamming distance during random search: {e}")
                     is_valid = False
                     break

            if is_valid:
                # Found a valid particle.
                # Assume distance >= 1, so it's guaranteed not in existing_particles_int.
                try:
                    return self._int_to_binary_list(candidate_int, dimension)
                except ValueError as e:
                     print(f"Error converting valid random integer {candidate_int} to binary list: {e}")
                     # Issue with conversion, try another random candidate.
                     pass

        # Time limit reached or search space exhausted
        if max_attempts_reached:
            print("Random search exhausted all possibilities.")
        else:
            print("Random search timed out.")
        return None

    def receive_message(self, message: Info) -> Info:
        next_particle: Optional[List[int]] = None
        try:
            # Extract data from the message
            data = message.message[0].data
            dimension: int = data['dimension']
            distance: int = data['distance']
            existing_particles_list: List[List[int]] = data['particles']

            # Basic Input Validation
            if dimension < 0 or distance < 0:
                raise ValueError("Dimension and distance cannot be negative")

            # Convert particles to integer representation
            existing_particles_int = {self._list_to_int(p) for p in existing_particles_list}

            # Handle dimension 0 explicitly
            if dimension == 0:
                 # Only one point exists: [] (integer 0)
                 if 0 not in existing_particles_int:
                      next_particle = []
                 else:
                      next_particle = None # The only point is already taken
            # Choose search strategy based on dimension
            elif dimension < self.DIMENSION_THRESHOLD:
                # Use exhaustive search for smaller dimensions
                print(f"Using exhaustive search for dimension {dimension}...")
                next_particle = self._find_particle_exhaustive(dimension, distance, existing_particles_int)
            else:
                # Use randomized search for larger dimensions
                print(f"Using randomized search for dimension {dimension}...")
                next_particle = self._find_particle_random(dimension, distance, existing_particles_int, self.RANDOM_SEARCH_TIME_LIMIT)

        except (ValueError, TypeError) as e:
            # Catch known potential errors during processing
            print(f"Error processing game state or finding particle: {e}")
            next_particle = None # Ensure None is returned on error
        except Exception as e:
             # Catch any other unexpected errors
             print(f"An unexpected error occurred: {e}")
             next_particle = None # Fail safe

        # Prepare and return the response message
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_particle, type='custom')]
        )
